import * as fs from 'fs';

// Read .env.test file
const envFile = fs.readFileSync('.env.test', 'utf-8');
const envLines = envFile.split('\n').filter(line => line.trim() !== '' && !line.startsWith('#'));

// Parse into key-value pairs
const envs = Object.fromEntries(
  envLines
    .map(line => line.split('=', 2))
    .filter(([key, value]) => key && value)
    .map(([key, value]) => [key.trim(), value.trim()])
);

// Post to the API
const response = await fetch('http://localhost:3003/api/doc-export', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify(envs)
});

if (response.ok) {
  console.log('Successfully posted environment variables to documentation wiki');
} else {
  console.error('Failed to post environment variables:', await response.text());
  process.exit(1);
}

